import{z as n,x as p,o as r,c as d,q as o,j as s,D as A,d as t,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"ARP 欺骗","description":"","frontmatter":{"title":"ARP 欺骗","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/arp-spoofing.md","filePath":"cs/arp-spoofing.md","lastUpdated":1791063341000}'),B={name:"cs/arp-spoofing.md"};function T(P,a,m,h,C,c){const E=p("Mermaid");return r(),d("div",null,[a[2]||(a[2]=o('<h1 id="arp-欺骗" tabindex="-1">ARP 欺骗 <a class="header-anchor" href="#arp-欺骗" aria-label="Permalink to &quot;ARP 欺骗&quot;">​</a></h1><div class="epigraph"><p>以太网用 ARP 问「谁有这个 IP」。谁先答、答得勤，谁就能当网关。这是局域网的映射欺骗，不是路由协议的全球问题。</p><footer>—— 据 Plummer, RFC 826；对照 Cisco/IANA 对动态 ARP 检查一类防御</footer></div><p>上一课<a href="/cs/dns-cache-poisoning">DNS 投毒</a>在三层之上。缺口是<strong>同网段</strong>：ARP 无认证。本课收机制与交换机侧防御，不给欺骗操作步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主机把 MAC 写入 ARP 表后，帧发往攻击者网卡，再转发则成中间人。对 TLS 仍要验证书；明文 HTTP 与内部无 TLS 服务会直接泄漏。缺口是二层信任假设，不是再讲以太网帧。</p><p><span class="marginnote">术语翻译：中间人（MITM）指攻击者卡在两台主机的必经之路上——不破译你的密码，而是站在门口把每张明信片抄一遍再转交。ARP 欺骗正是链路层里最便宜的「占路口」手段。</span></p><h3 id="静态表与-dai" tabindex="-1">静态表与 DAI <a class="header-anchor" href="#静态表与-dai" aria-label="Permalink to &quot;静态表与 DAI&quot;">​</a></h3><p>关键主机可静态 ARP；交换机可做动态 ARP 检查绑定 DHCP 侦听。那是网络作业，不是密码学。</p><p><span class="marginnote">RFC 826。本课禁止 ARP 欺骗教程。无线客户端隔离是另一缓解。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>陈述：无认证的请求/应答、缓存覆盖。防御：分段、DAI、最小二层域、应用全 TLS。对照 VPN：远程用户进同一 L2 广播域会放大这条。</p>',12)),(r(),s(l,null,{default:A(()=>[i(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%B0%81%E6%9C%89%20IP%22%5D%20--%3E%20ANS%5B%22%E6%97%A0%E8%AE%A4%E8%AF%81%E5%BA%94%E7%AD%94%22%5D%0A%20%20ANS%20--%3E%20TAB%5B%22ARP%20%E8%A1%A8%E8%A2%AB%E5%86%99%22%5D%0A%20%20TAB%20--%3E%20MITM%5B%22%E5%B8%A7%E8%B5%B0%E5%90%91%E9%94%99%E8%AF%AF%20MAC%22%5D%0A%20%20TLS%5B%22%E5%BA%94%E7%94%A8%20TLS%20%E9%AA%8C%E5%90%8D%22%5D%20-.-%3E%7C%22%E4%BB%8D%E5%8F%AF%E6%8B%A6%E5%86%92%E5%85%85%20HTTPS%22%7C%20MITM%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"信道单元收口：从证书、无线、DNS 到 ARP，每一层都有「映射可被骗」。下一课序身份：应用如何发令牌——JWT 常把映射问题换成签名问题，然后自己关验签。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为「换更强的加密算法」就能防 ARP 欺骗。AES 再强，也架不住你把密钥交给了冒充的网关——病灶是「谁是谁」的映射没有认证，防御要对症：收窄广播域、交换机 DAI、应用层全 TLS。")],-1)),(r(),s(l,null,{default:A(()=>[i(E,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20ATK%5B%22%E6%94%BB%E5%87%BB%E8%80%85%22%5D%20--%3E%7C%22%E8%B0%8E%E7%A7%B0%3A%20%E7%BD%91%E5%85%B3%E7%9A%84%20MAC%20%E6%98%AF%E6%88%91%22%7C%20A%5B%22%E4%B8%BB%E6%9C%BA%20A%20%E7%9A%84%20ARP%20%E8%A1%A8%22%5D%0A%20%20ATK%20--%3E%7C%22%E8%B0%8E%E7%A7%B0%3A%20A%20%E7%9A%84%20MAC%20%E6%98%AF%E6%88%91%22%7C%20GW%5B%22%E7%BD%91%E5%85%B3%E7%9A%84%20ARP%20%E8%A1%A8%22%5D%0A%20%20A%20--%3E%7C%22%E5%8F%91%E5%BE%80%E7%BD%91%E5%85%B3%E7%9A%84%E5%B8%A7%E5%85%88%E8%BF%9B%E6%94%BB%E5%87%BB%E8%80%85%22%7C%20ATK%0A%20%20ATK%20--%3E%7C%22%E5%86%8D%E8%BD%AC%E7%BB%99%E7%9C%9F%E7%BD%91%E5%85%B3%22%7C%20GW%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写交换机 CAM 溢出步骤。JWT 下一课：令牌合同。</p><p><span class="marginnote">为什么重要：只骗一边，攻击者多看一台主机的流量；同时骗主机和网关两边，它就坐上中转位，全段明文一网打尽。这正是「最小二层域」的价值——广播域越小，能被骗进同一场戏的角色越少。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DNS 骗名字；ARP 骗同网段 MAC。</li><li>无认证映射；防御在分段与检查，不在更长 AES。</li><li>应用 TLS 仍是安全带。</li><li>下一课序：JWT 陷阱。</li><li>出处：RFC 826；对照 Anderson 对链路层信任；NIST 对分段的讨论。</li></ul>',5))])}const u=n(B,[["render",T]]);export{f as __pageData,u as default};
